 "b1-private-s3/alternative": {
  "main.tf": "# Same requirements, different valid choices: provider default_tags instead\n# of a tags argument on each resource, SSE-KMS with the AWS managed key and a\n# bucket key, and different local names.\nterraform {\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n\n  default_tags {\n    tags = {\n      project     = \"ridgeline\"\n      environment = var.environment\n      managed_by  = \"terraform\"\n    }\n  }\n}\n\nresource \"aws_s3_bucket\" \"this\" {\n  bucket = var.bucket_name\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"this\" {\n  bucket                  = aws_s3_bucket.this.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_versioning\" \"this\" {\n  bucket = aws_s3_bucket.this.bucket\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"this\" {\n  bucket = aws_s3_bucket.this.id\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = \"aws:kms\"\n    }\n    bucket_key_enabled = true\n  }\n}\n",
  "outputs.tf": "output \"name\" {\n  value = aws_s3_bucket.this.bucket\n}\n\noutput \"arn\" {\n  value = aws_s3_bucket.this.arn\n}\n",
  "variables.tf": "variable \"region\" {\n  type    = string\n  default = \"us-west-2\"\n}\n\nvariable \"environment\" {\n  type    = string\n  default = \"dev\"\n}\n\nvariable \"bucket_name\" {\n  type = string\n}\n"
 },
 "b1-private-s3/guided": {
  "main.tf": "# Build 1 (guided): a private bucket for operations artifacts.\n# Work top to bottom. The first three resources are written for you with\n# notes; you write the encryption resource, the tags and the outputs.\nterraform {\n  required_version = \">= 1.6.0, < 2.0.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\" # which provider plugin to download\n      version = \"~> 6.60\"       # any 6.x from 6.60 on, never 7.0\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region # credentials are NOT set here; see the lesson\n}\n\nlocals {\n  tags = {\n    project = var.project\n    # TODO: add environment = var.environment once you declare that variable\n  }\n}\n\n# resource TYPE \"aws_s3_bucket\", LOCAL NAME \"artifacts\".\n# The REMOTE name in AWS is var.bucket_name — a third, different thing.\nresource \"aws_s3_bucket\" \"artifacts\" {\n  bucket = var.bucket_name\n  tags   = local.tags\n}\n\n# Each of these manages one aspect of the same bucket. The reference\n# aws_s3_bucket.artifacts.id is what ties them to it (and orders creation).\nresource \"aws_s3_bucket_public_access_block\" \"artifacts\" {\n  bucket = aws_s3_bucket.artifacts.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_versioning\" \"artifacts\" {\n  bucket = aws_s3_bucket.artifacts.id\n\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\n# TODO: aws_s3_bucket_server_side_encryption_configuration for the same bucket:\n#   rule { apply_server_side_encryption_by_default { sse_algorithm = \"AES256\" } }\n",
  "outputs.tf": "# TODO: output \"bucket_name\" — the bucket's id attribute\n# TODO: output \"bucket_arn\"  — the bucket's arn attribute\n",
  "variables.tf": "variable \"region\" {\n  type    = string\n  default = \"us-east-1\"\n}\n\nvariable \"project\" {\n  type    = string\n  default = \"ridgeline\"\n}\n\n# Bucket names are global across all AWS accounts: pick something only you\n# would use, 3-63 lowercase letters, digits, dots or hyphens.\nvariable \"bucket_name\" {\n  type = string\n}\n\n# TODO: variable \"environment\" (type string, default \"dev\")\n"
 },
 "b1-private-s3/reference": {
  "main.tf": "terraform {\n  required_version = \">= 1.6.0, < 2.0.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\n# Credentials come from your environment (AWS_PROFILE, SSO, instance role),\n# never from this file.\nprovider \"aws\" {\n  region = var.region\n}\n\nlocals {\n  tags = {\n    project     = var.project\n    environment = var.environment\n    purpose     = \"ops-artifacts\"\n    managed_by  = \"terraform\"\n  }\n}\n\n# The bucket itself. Everything else about it is a separate resource that\n# points back here with bucket = aws_s3_bucket.artifacts.id.\nresource \"aws_s3_bucket\" \"artifacts\" {\n  bucket = var.bucket_name\n  tags   = local.tags\n  # force_destroy is left at its default (false): Terraform will refuse to\n  # delete a bucket that still holds objects.\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"artifacts\" {\n  bucket = aws_s3_bucket.artifacts.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_versioning\" \"artifacts\" {\n  bucket = aws_s3_bucket.artifacts.id\n\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"artifacts\" {\n  bucket = aws_s3_bucket.artifacts.id\n\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = \"AES256\"\n    }\n  }\n}\n",
  "outputs.tf": "output \"bucket_name\" {\n  value = aws_s3_bucket.artifacts.id\n}\n\noutput \"bucket_arn\" {\n  value = aws_s3_bucket.artifacts.arn\n}\n",
  "variables.tf": "variable \"region\" {\n  description = \"AWS Region for the bucket.\"\n  type        = string\n  default     = \"us-east-1\"\n}\n\nvariable \"project\" {\n  type    = string\n  default = \"ridgeline\"\n}\n\nvariable \"environment\" {\n  type    = string\n  default = \"dev\"\n}\n\nvariable \"bucket_name\" {\n  description = \"Globally unique S3 bucket name you choose, e.g. ridgeline-ops-artifacts-<your initials>-<random digits>.\"\n  type        = string\n\n  validation {\n    condition     = can(regex(\"^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$\", var.bucket_name))\n    error_message = \"Use 3-63 lowercase letters, digits, dots or hyphens, starting and ending with a letter or digit.\"\n  }\n}\n"
 },
