 "b4-independent/change-reference": {
  "main.tf": "terraform {\n  required_version = \">= 1.6.0, < 2.0.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n}\n\nlocals {\n  tags = merge({\n    project    = var.name\n    managed_by = \"terraform\"\n  }, var.extra_tags)\n  az = coalesce(var.availability_zone, data.aws_availability_zones.available.names[0])\n}\n\ndata \"aws_availability_zones\" \"available\" {\n  state = \"available\"\n}\n\ndata \"aws_ami\" \"al2023\" {\n  most_recent = true\n  owners      = [\"amazon\"]\n\n  filter {\n    name   = \"name\"\n    values = [\"al2023-ami-2023.*-x86_64\"]\n  }\n\n  filter {\n    name   = \"architecture\"\n    values = [\"x86_64\"]\n  }\n}\n\nresource \"aws_vpc\" \"main\" {\n  cidr_block           = var.vpc_cidr\n  enable_dns_support   = true\n  enable_dns_hostnames = true\n  tags                 = merge(local.tags, { Name = \"${var.name}-vpc\" })\n}\n\n# ── public side: where the NAT gateway lives ────────────────────────\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = var.public_subnet_cidr\n  availability_zone = local.az\n  tags              = merge(local.tags, { Name = \"${var.name}-public\" })\n}\n\nresource \"aws_internet_gateway\" \"main\" {\n  vpc_id = aws_vpc.main.id\n  tags   = local.tags\n}\n\nresource \"aws_route_table\" \"public\" {\n  vpc_id = aws_vpc.main.id\n  tags   = merge(local.tags, { Name = \"${var.name}-public\" })\n}\n\nresource \"aws_route\" \"public_default\" {\n  route_table_id         = aws_route_table.public.id\n  destination_cidr_block = \"0.0.0.0/0\"\n  gateway_id             = aws_internet_gateway.main.id\n}\n\nresource \"aws_route_table_association\" \"public\" {\n  subnet_id      = aws_subnet.public.id\n  route_table_id = aws_route_table.public.id\n}\n\n# A public NAT gateway needs an Elastic IP and must sit in a PUBLIC subnet:\n# it forwards the worker's traffic out through the internet gateway.\nresource \"aws_eip\" \"nat\" {\n  domain = \"vpc\"\n  tags   = merge(local.tags, { Name = \"${var.name}-nat\" })\n}\n\nresource \"aws_nat_gateway\" \"main\" {\n  allocation_id = aws_eip.nat.id\n  subnet_id     = aws_subnet.public.id\n  tags          = merge(local.tags, { Name = \"${var.name}-nat\" })\n\n  # The NAT gateway is only useful once the VPC has an attached IGW, and no\n  # argument above references the IGW.\n  depends_on = [aws_internet_gateway.main]\n}\n\n# ── private side: the worker ────────────────────────────────────────\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = var.private_subnet_cidr\n  availability_zone = local.az\n  tags              = merge(local.tags, { Name = \"${var.name}-private\" })\n}\n\nresource \"aws_subnet\" \"private_2\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = var.private_subnet_2_cidr\n  availability_zone = local.az\n  tags              = merge(local.tags, { Name = \"${var.name}-private-2\" })\n}\n\nresource \"aws_route_table\" \"private\" {\n  vpc_id = aws_vpc.main.id\n  tags   = merge(local.tags, { Name = \"${var.name}-private\" })\n}\n\nresource \"aws_route\" \"private_default\" {\n  route_table_id         = aws_route_table.private.id\n  destination_cidr_block = \"0.0.0.0/0\"\n  nat_gateway_id         = aws_nat_gateway.main.id\n}\n\nresource \"aws_route_table_association\" \"private\" {\n  subnet_id      = aws_subnet.private.id\n  route_table_id = aws_route_table.private.id\n}\n\nresource \"aws_route_table_association\" \"private_2\" {\n  subnet_id      = aws_subnet.private_2.id\n  route_table_id = aws_route_table.private.id\n}\n\n# Stateful: replies to the worker's outbound connections are allowed back\n# in automatically, so there is no ingress rule at all.\nresource \"aws_security_group\" \"worker\" {\n  name_prefix = \"${var.name}-worker-\"\n  description = \"Outbound HTTPS only; no inbound\"\n  vpc_id      = aws_vpc.main.id\n  tags        = local.tags\n}\n\nresource \"aws_vpc_security_group_egress_rule\" \"worker_https\" {\n  security_group_id = aws_security_group.worker.id\n  ip_protocol       = \"tcp\"\n  from_port         = 443\n  to_port           = 443\n  cidr_ipv4         = \"0.0.0.0/0\"\n}\n\nresource \"aws_instance\" \"worker\" {\n  ami                         = data.aws_ami.al2023.id\n  instance_type               = var.instance_type\n  subnet_id                   = aws_subnet.private.id\n  vpc_security_group_ids      = [aws_security_group.worker.id]\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  user_data = <<-EOT\n    #!/bin/bash\n    set -euo pipefail\n    dnf install -y jq\n    echo \"worker bootstrapped\" > /var/log/worker-bootstrap.log\n  EOT\n\n  # The bootstrap needs egress through the NAT gateway at first boot.\n  depends_on = [aws_route.private_default, aws_route_table_association.private]\n\n  tags = merge(local.tags, { Name = \"${var.name}-worker\" })\n}\n",
  "outputs.tf": "output \"public_subnet_id\" {\n  value = aws_subnet.public.id\n}\n\noutput \"private_subnet_id\" {\n  value = aws_subnet.private.id\n}\n\noutput \"private_subnet_2_id\" {\n  value = aws_subnet.private_2.id\n}\n\noutput \"worker_private_ip\" {\n  value = aws_instance.worker.private_ip\n}\n\noutput \"nat_gateway_id\" {\n  value = aws_nat_gateway.main.id\n}\n",
  "variables.tf": "variable \"region\" {\n  type    = string\n  default = \"us-east-2\"\n}\n\nvariable \"availability_zone\" {\n  type    = string\n  default = null\n}\n\nvariable \"name\" {\n  description = \"Prefix for Name tags.\"\n  type        = string\n  default     = \"harbor-jobs\"\n}\n\nvariable \"vpc_cidr\" {\n  type    = string\n  default = \"10.80.0.0/16\"\n}\n\nvariable \"public_subnet_cidr\" {\n  type    = string\n  default = \"10.80.0.0/24\"\n}\n\nvariable \"private_subnet_cidr\" {\n  type    = string\n  default = \"10.80.20.0/24\"\n}\n\nvariable \"private_subnet_2_cidr\" {\n  description = \"Change request: a second private subnet, same AZ is acceptable.\"\n  type        = string\n  default     = \"10.80.21.0/24\"\n}\n\nvariable \"instance_type\" {\n  type    = string\n  default = \"t3.micro\"\n}\n\nvariable \"extra_tags\" {\n  description = \"Tags added to every resource.\"\n  type        = map(string)\n  default     = {}\n}\n"
 },
