 "b5-iteration/foreach-reference": {
  "main.tf": "terraform {\n  required_version = \">= 1.6.0, < 2.0.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n}\n\nresource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.90.0.0/16\"\n}\n\nresource \"aws_route_table\" \"private\" {\n  vpc_id = aws_vpc.main.id\n}\n\n# One block, one instance per map key: aws_subnet.private[\"a\"], [\"b\"].\n# Keys are stable names, so adding \"c\" later never renumbers \"a\" or \"b\".\nresource \"aws_subnet\" \"private\" {\n  for_each = var.private_subnets\n\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = each.value.cidr\n  availability_zone = \"${var.region}${each.value.az_suffix}\"\n\n  tags = {\n    Name = \"private-${each.key}\"\n  }\n}\n\n# Iterate over the subnets themselves, so every subnet gets exactly one\n# association and the keys line up.\nresource \"aws_route_table_association\" \"private\" {\n  for_each = aws_subnet.private\n\n  subnet_id      = each.value.id\n  route_table_id = aws_route_table.private.id\n}\n",
  "outputs.tf": "# A map from key to subnet ID, built from the collection.\noutput \"private_subnet_ids\" {\n  value = { for key, subnet in aws_subnet.private : key => subnet.id }\n}\n",
  "variables.tf": "variable \"region\" {\n  type    = string\n  default = \"us-east-1\"\n}\n\nvariable \"private_subnets\" {\n  description = \"Private subnets keyed by a stable short name.\"\n  type = map(object({\n    cidr      = string\n    az_suffix = string\n  }))\n  default = {\n    a = { cidr = \"10.90.10.0/24\", az_suffix = \"a\" }\n    b = { cidr = \"10.90.11.0/24\", az_suffix = \"b\" }\n  }\n}\n"
 },
 "b5-iteration/foreach-start": {
  "main.tf": "terraform {\n  required_version = \">= 1.6.0, < 2.0.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n}\n\n# Two private subnets written out by hand. They differ only in CIDR and AZ,\n# and each needs its own association — easy to forget the second one.\nresource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.90.0.0/16\"\n}\n\nresource \"aws_route_table\" \"private\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_subnet\" \"private_a\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.90.10.0/24\"\n  availability_zone = \"${var.region}a\"\n}\n\nresource \"aws_subnet\" \"private_b\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.90.11.0/24\"\n  availability_zone = \"${var.region}b\"\n}\n\nresource \"aws_route_table_association\" \"private_a\" {\n  subnet_id      = aws_subnet.private_a.id\n  route_table_id = aws_route_table.private.id\n}\n\nresource \"aws_route_table_association\" \"private_b\" {\n  subnet_id      = aws_subnet.private_a.id\n  route_table_id = aws_route_table.private.id\n}\n",
  "outputs.tf": "output \"private_subnet_ids\" {\n  value = [aws_subnet.private_a.id, aws_subnet.private_b.id]\n}\n",
  "variables.tf": "variable \"region\" {\n  type    = string\n  default = \"us-east-1\"\n}\n"
 },
 "b5-iteration/param-reference": {
  "main.tf": "terraform {\n  required_version = \">= 1.6.0, < 2.0.0\"\n\n  required_providers {\n    aws = {\n      source  = \"hashicorp/aws\"\n      version = \"~> 6.60\"\n    }\n  }\n}\n\nprovider \"aws\" {\n  region = var.region\n}\n\nlocals {\n  # Derive the subnet from the VPC range instead of repeating a literal.\n  app_subnet_cidr = cidrsubnet(var.vpc_cidr, 8, 1)\n}\n\ndata \"aws_ami\" \"al2023\" {\n  most_recent = true\n  owners      = [\"amazon\"]\n\n  filter {\n    name   = \"name\"\n    values = [\"al2023-ami-2023.*-x86_64\"]\n  }\n}\n\nresource \"aws_vpc\" \"main\" {\n  cidr_block = var.vpc_cidr\n}\n\nresource \"aws_subnet\" \"app\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = local.app_subnet_cidr\n}\n\nresource \"aws_instance\" \"app\" {\n  ami           = data.aws_ami.al2023.id\n  instance_type = var.instance_type\n  subnet_id     = aws_subnet.app.id\n}\n",
  "outputs.tf": "output \"instance_id\" {\n  value = aws_instance.app.id\n}\n",
  "variables.tf": "variable \"region\" {\n  type    = string\n  default = \"us-east-1\"\n}\n\nvariable \"vpc_cidr\" {\n  description = \"VPC range; must leave room for /24 subnets.\"\n  type        = string\n  default     = \"10.60.0.0/16\"\n\n  validation {\n    condition     = can(cidrhost(var.vpc_cidr, 0)) && tonumber(split(\"/\", var.vpc_cidr)[1]) <= 22\n    error_message = \"vpc_cidr must be an IPv4 CIDR no smaller than /22.\"\n  }\n}\n\nvariable \"instance_type\" {\n  description = \"x86_64 types only, to match the AL2023 x86_64 AMI.\"\n  type        = string\n  default     = \"t3.micro\"\n\n  validation {\n    condition     = contains([\"t3.micro\", \"t3.small\", \"t3.medium\"], var.instance_type)\n    error_message = \"Choose t3.micro, t3.small or t3.medium.\"\n  }\n}\n"
 },
